import { NextRequest, NextResponse } from 'next/server';
import { GoogleGenerativeAI } from '@google/generative-ai';

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY || '');

export async function POST(req: NextRequest) {
    try {
        const { query } = await req.json();

        // Use Gemini to recall famous CP blogs
        const model = genAI.getGenerativeModel({
            model: "gemini-1.5-flash",
            generationConfig: { responseMimeType: "application/json" }
        });

        const prompt = `
        You are an expert Competitive Programmer. The user is searching for tutorials on: "${query}".
        Return a JSON object with a list of 5-10 BEST Codeforces (or similar high quality) blog tutorials for this topic.
        Prioritize:
        1. Official Codeforces Edu / Pilot Course materials if applicable.
        2. Famous blogs (e.g. by tourist, adamant, cp-algorithms).
        3. Clear explanations over obscure tricks.

        JSON Format:
        {
            "results": [
                { "title": "...", "url": "...", "author": "...", "snippet": "..." }
            ]
        }
        `;

        const result = await model.generateContent(prompt);
        const responseText = result.response.text();
        const data = JSON.parse(responseText);

        return NextResponse.json(data);

    } catch (error) {
        console.error(error);
        return NextResponse.json({ error: "Failed to fetch blogs" }, { status: 500 });
    }
}
